#!/usr/bin/env python3
"""
Test all models listed in a JSON config file by sending:
  "Reply with exactly one word: OK"
to an OpenAI-compatible Chat Completions API at:
  http://127.0.0.1:4000/v1/chat/completions

Usage:
  python test_models.py path/to/config.json
"""

import sys
import json
import time
import urllib.request
import urllib.error

API_URL = "http://127.0.0.1:4000/v1/chat/completions"
PROMPT = "Reply with exactly one word: OK"
TIMEOUT_SECS = 30
MAX_TOKENS = 20


def load_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def extract_models(cfg):
    """
    Accepts common shapes:
      - ["model-a", "model-b"]
      - {"models": ["model-a", ...]}
      - {"models": [{"name": "model-a"}, {"id": "model-b"}]}
      - {"model_list": [...]}, {"available_models": [...]}, {"data": [...]}
    Returns list of model name strings.
    """
    if isinstance(cfg, list):
        items = cfg
    elif isinstance(cfg, dict):
        for key in ("models", "model_list", "available_models", "data"):
            if key in cfg and isinstance(cfg[key], list):
                items = cfg[key]
                break
        else:
            # As a fallback, if dict has a single list value, use it
            list_values = [v for v in cfg.values() if isinstance(v, list)]
            if len(list_values) == 1:
                items = list_values[0]
            else:
                raise ValueError("Could not find a model list in the JSON config.")
    else:
        raise ValueError("Config JSON must be a list or an object containing a list of models.")

    models = []
    for it in items:
        if isinstance(it, str):
            name = it
        elif isinstance(it, dict):
            name = it.get("name") or it.get("id") or it.get("model")
        else:
            name = None

        if not name or not isinstance(name, str):
            raise ValueError(f"Unrecognized model entry: {it!r}")
        models.append(name)

    # De-duplicate while preserving order
    seen = set()
    out = []
    for m in models:
        if m not in seen:
            seen.add(m)
            out.append(m)
    return out


def parse_chat_content(resp_obj):
    """
    Tries to extract assistant content from OpenAI-style responses.
    """
    # Standard: {"choices":[{"message":{"content":"..."}}]}
    try:
        choices = resp_obj.get("choices") or []
        if choices:
            msg = choices[0].get("message") or {}
            if "content" in msg and msg["content"] is not None:
                return str(msg["content"])
            # Some servers may return {"choices":[{"text":"..."}]}
            if "text" in choices[0] and choices[0]["text"] is not None:
                return str(choices[0]["text"])
    except Exception:
        pass
    return ""


def looks_like_temperature_unsupported(err_obj, err_text):
    """
    Detect errors that indicate the server/model doesn't accept 'temperature'.
    """
    try:
        e = err_obj.get("error") or {}
        param = e.get("param")
        msg = (e.get("message") or "").lower()
        if param == "temperature":
            return True
        if "temperature" in msg and ("unsupported" in msg or "unknown" in msg or "unexpected" in msg):
            return True
    except Exception:
        pass

    t = (err_text or "").lower()
    if "temperature" in t and ("unsupported" in t or "unknown" in t or "unexpected" in t):
        return True
    return False


def post_chat_completion(payload, timeout_secs=TIMEOUT_SECS):
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        API_URL,
        data=data,
        method="POST",
        headers={
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
    )

    with urllib.request.urlopen(req, timeout=timeout_secs) as resp:
        raw = resp.read().decode("utf-8", errors="replace")
        obj = json.loads(raw) if raw else {}
        return resp.getcode(), obj, raw


def test_model(model_name):
    """
    Returns dict with: model, ok(bool), latency(float), response(str)
    Retries without temperature if temperature is unsupported.
    """
    base_payload = {
        "model": model_name,
        "messages": [
            {"role": "user", "content": PROMPT}
        ],
        "max_tokens": MAX_TOKENS,
    }

    # First attempt includes temperature.
    payload = dict(base_payload)
    payload["temperature"] = 0

    start = time.perf_counter()
    try:
        code, obj, raw = post_chat_completion(payload, TIMEOUT_SECS)
        latency = time.perf_counter() - start

        if code != 200:
            # Treat non-200 as failure, but still attempt to parse error
            content = parse_chat_content(obj)
            if not content:
                content = (obj.get("error") or {}).get("message") or raw or f"HTTP {code}"
            return {"model": model_name, "ok": False, "latency": latency, "response": content}

        content = parse_chat_content(obj)
        ok = (content.strip() == "OK")
        return {"model": model_name, "ok": ok, "latency": latency, "response": content}

    except urllib.error.HTTPError as e:
        latency = time.perf_counter() - start
        raw = ""
        obj = {}
        try:
            raw = e.read().decode("utf-8", errors="replace")
            obj = json.loads(raw) if raw else {}
        except Exception:
            pass

        # If temperature unsupported, retry once without it
        if looks_like_temperature_unsupported(obj, raw):
            start2 = time.perf_counter()
            try:
                code2, obj2, raw2 = post_chat_completion(base_payload, TIMEOUT_SECS)
                latency2 = time.perf_counter() - start2
                content2 = parse_chat_content(obj2)
                ok2 = (code2 == 200 and content2.strip() == "OK")
                if not content2 and code2 != 200:
                    content2 = (obj2.get("error") or {}).get("message") or raw2 or f"HTTP {code2}"
                return {"model": model_name, "ok": ok2, "latency": latency2, "response": content2}
            except Exception as e2:
                latency2 = time.perf_counter() - start2
                return {"model": model_name, "ok": False, "latency": latency2, "response": str(e2)}

        msg = (obj.get("error") or {}).get("message") or raw or f"HTTPError {getattr(e, 'code', '')}"
        return {"model": model_name, "ok": False, "latency": latency, "response": msg}

    except Exception as e:
        latency = time.perf_counter() - start
        return {"model": model_name, "ok": False, "latency": latency, "response": str(e)}


def format_table(rows):
    # Prepare display values
    display = []
    for r in rows:
        resp = (r.get("response") or "").replace("\n", " ").strip()
        if len(resp) > 50:
            resp = resp[:50]
        status = "PASS" if r.get("ok") else "FAIL"
        latency = r.get("latency")
        latency_s = f"{latency:.3f}" if isinstance(latency, (int, float)) else ""
        display.append((r.get("model", ""), status, latency_s, resp))

    headers = ("Model", "Status", "Latency", "Response")
    cols = list(zip(*([headers] + display))) if display else [headers, (), (), ()]
    widths = [max(len(str(x)) for x in col) for col in cols]

    def line(parts):
        return "  ".join(str(p).ljust(w) for p, w in zip(parts, widths))

    out = []
    out.append(line(headers))
    out.append("  ".join("-" * w for w in widths))
    for row in display:
        out.append(line(row))
    return "\n".join(out)


def main(argv):
    if len(argv) != 2:
        print("Usage: python test_models.py path/to/config.json", file=sys.stderr)
        return 2

    cfg_path = argv[1]
    try:
        cfg = load_json(cfg_path)
        models = extract_models(cfg)
    except Exception as e:
        print(f"Failed to load/parse config: {e}", file=sys.stderr)
        return 2

    results = []
    for m in models:
        results.append(test_model(m))

    print(format_table(results))

    total = len(results)
    working = sum(1 for r in results if r.get("ok"))
    failed = total - working
    print(f"Total: {total} models | ✅ {working} working | ❌ {failed} failed")
    return 0 if failed == 0 else 1


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
